FIELDS = ['meta', 'seo_title', 'tags', 'headline', 'subtitle']
for a in A:
    art = {'_note': 'Створено 14.11.2026 (tools/new_articles_2026_11.py) після огляду блогів silent disco компаній; тексти за фактами PRODUCT.md, стиль за скілом humanizer.'}
    for k in FIELDS: art[k] = a[k]
    art.update({'author': 'Команда SILENT', 'date': DATE, 'read': a['read'], 'date_iso': DATE_ISO, 'modified_iso': DATE_ISO,
                'cover': a['cover'], 'og': '/images/blog/og-%s.jpg' % a['slug'], 'lead': a['lead'], 'blocks': a['blocks'],
                'faq': a['faq'], 'related': a['related'], 'cta': a['cta']})
    json.dump(art, open(os.path.join(SRC, a['slug'] + '.json'), 'w', encoding='utf-8'), ensure_ascii=False, indent=1)

pp = os.path.join(SRC, 'posts.json')
d = json.load(open(pp, encoding='utf-8'))
have = {p['slug'] for p in d['posts']}
for a in A:
    if a['slug'] in have: continue
    d['posts'].append({'slug': a['slug'], 'status': 'published', 'category': a['category'], 'title': a['title'],
                       'excerpt': a['excerpt'], 'image': a['cover']['src'], 'alt': a['cover']['alt'], 'also': a['also']})
json.dump(d, open(pp, 'w', encoding='utf-8'), ensure_ascii=False, indent=1)
print('ok', len(A))
